'use strict';

// Standalone B1-A interaction model. Synthetic data only; no API or persistence.
const $ = (selector, root = document) => root.querySelector(selector);
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHtml;
const paths = {
  mark:'M3 12h4l3-8 4 16 3-8h4', today:'M4 5h16v15H4z M8 3v4 M16 3v4 M4 10h16 M8 14h3 M8 17h6',
  people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',
  calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 18h2',
  chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5Z M8 10h8 M8 14h5',
  plus:'M12 5v14 M5 12h14', arrow:'M5 12h14 M13 6l6 6-6 6', back:'M19 12H5 M11 6l-6 6 6 6',
  check:'M5 12l4 4L19 6', close:'M6 6l12 12 M18 6 6 18', document:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',
  clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2', send:'m3 3 18 9-18 9 4-9-4-9 M7 12h14',
  lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3', meal:'M4 3v7a3 3 0 0 0 6 0V3 M7 3v18 M17 3v18 M17 3c4 3 4 8 0 9',
};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.document}"/></svg>`;}
const btn = (text, action, cls = '', attrs = '') => `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const dateLabel = value => {const [y,m,d]=value.split('-');return `${d}/${m}/${y}`;};
const goals = {fat_loss:'Giảm mỡ',muscle_gain:'Tăng cơ',recomp:'Cải thiện thành phần cơ thể'};
const metrics = [
  ['weight','Cân nặng','kg',70.4],['smm','Khối cơ xương','kg',30.2],['fat','Khối lượng mỡ','kg',20.4],
  ['pbf','Tỷ lệ mỡ cơ thể','%',29],['water','Tổng nước cơ thể','L',37.1],['ffm','Khối không mỡ','kg',50],
  ['protein','Protein trên phiếu','kg',10.1],['minerals','Khoáng chất','kg',2.8],['bmi','BMI','kg/m²',24.4],
];
const segmentNames = [['left_arm','Tay trái'],['right_arm','Tay phải'],['trunk','Thân'],['left_leg','Chân trái'],['right_leg','Chân phải']];
const segmentValues = [[2.28,1.3,94],[2.33,1.4,96],[20.1,9.2,101],[7.5,3.4,99],[7.6,3.2,100]];
function sampleFields(){const fields=Object.fromEntries(metrics.map(m=>[m[0],String(m[3])]));segmentNames.forEach(([key],i)=>{fields[key+'_lean']=String(segmentValues[i][0]);fields[key+'_fat']=String(segmentValues[i][1]);fields[key+'_ref']=String(segmentValues[i][2]);});return {...fields,bmr:'1490',visceral_level:'8',ecw_ratio:'0.378',score:'76'};}
function initialState(){return {
  role:'pt',page:'today',tab:'overview',progressMetric:'weight',landingMode:'profile',selected:'linh',scenario:'normal',day:'2026-10-30',reviewTab:'total',draft:null,sourceReady:false,manual:false,busy:false,
  trainees:[
    {id:'linh',name:'Khánh Linh',history:[{date:'2026-10-02',weight:72.1,pbf:30.8,smm:29.8},{date:'2026-10-09',weight:71.6,pbf:30.1,smm:30.0},{date:'2026-10-16',weight:71.0,pbf:29.6,smm:30.1}],goal:'fat_loss',linked:true,start:'2026-10-01',end:'2026-12-31',total:12,remaining:8,report:{fields:sampleFields(),date:'2026-10-23',source:'ocr_reviewed'},notes:['Buổi trước học viên muốn giảm tải ở phần cuối. Hỏi lại mức độ thoải mái trước khi bắt đầu.'],shared:'Giữ nhịp tập đều, trao đổi với PT nếu có thay đổi trong sinh hoạt.',ledger:[],target:{kcal:1900,protein:130,carbs:210,fat:60}},
    {id:'khoa',name:'Minh Khoa',goal:'muscle_gain',linked:true,start:'2026-10-15',end:'2027-01-15',total:24,remaining:21,report:null,notes:[],shared:'Theo dõi việc ăn uống và lịch tập trong tuần.',ledger:[],target:null},
    {id:'nam',name:'Hoàng Nam',goal:'recomp',linked:false,start:'2026-10-30',end:'2026-11-30',total:8,remaining:8,report:null,notes:[],shared:'',ledger:[],target:null},
  ],
  appointments:[{id:'a1',trainee:'khoa',date:'2026-10-30',time:'09:00',duration:60,type:'Buổi cùng PT',status:'confirmed',exercises:[]},{id:'a2',trainee:'linh',date:'2026-10-30',time:'16:00',duration:60,type:'Buổi cùng PT',status:'confirmed',exercises:[]},{id:'a3',trainee:'nam',date:'2026-10-30',time:'17:30',duration:45,type:'Tư vấn ban đầu',status:'confirmed',exercises:[]}],
  request:null,messages:[{trainee:'linh',author:'pt',text:'Chiều nay mình gặp nhau lúc 16:00 nhé. Nếu cần đổi giờ, em gửi yêu cầu ngay trong lịch này.',time:'09:10'},{trainee:'linh',author:'trainee',text:'Dạ, chiều em tới. Em đã gửi cập nhật bữa trưa để anh xem trước.',time:'11:45'}],selfCheckins:[],
};}
let state=initialState();let toastTimer;let sourceJob=0;
const trainee = () => state.trainees.find(t=>t.id===state.selected) || state.trainees[0];
const initials = name => name.split(' ').slice(-2).map(s=>s[0]).join('');
const avatar = t => `<span class="avatar ${t.id==='khoa'?'alt':''}" aria-hidden="true">${e(initials(t.name))}</span>`;
function toast(text){$('#announcements').textContent=text;const n=$('#toast');n.textContent=text;n.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{n.hidden=true;},4500);}
function setHash(){history.replaceState(null,'',`#${state.role}/${state.page}`);}
function go(page, tab){if(state.role==='trainee'&&['intake','review','reportStart','roster'].includes(page)){page='today';toast('Học viên chỉ xem thông tin của mình đã được PT chia sẻ.');}state.page=page;if(tab)state.tab=tab;else if(page==='profile')state.tab='overview';setHash();render();window.scrollTo({top:0,behavior:'instant'});$('#main-content')?.focus({preventScroll:true});}
function nav(){const list=state.role==='pt'?[['today','today','Hôm nay'],['roster','people','Học viên'],['calendar','calendar','Lịch'],['chat','chat','Tin nhắn']]:[['today','today','Hôm nay'],['calendar','calendar','Lịch'],['chat','chat','Tin nhắn'],['profile','people','Hồ sơ']];return list.map(([page,ic,label])=>`<button type="button" class="nav-button" data-nav="${page}" ${state.page===page?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('');}
function brand(){return `<span class="brand">${icon('mark')}<span>fitsync</span></span>`;}
function shell(content){
  const main = `<main id="main-content" tabindex="-1" data-view="${state.page}" data-role="${state.role}">${content}</main>`;
  if(state.page==='landing') return `<div class="public-shell">${main}</div>`;
  return `<aside class="sidebar">${brand()}<p class="workspace-name">${state.role==='pt'?'Không gian PT':'Không gian học viên'}</p><nav class="sidenav" aria-label="Điều hướng chính">${nav()}</nav><div class="account">${state.role==='pt'?'<span class="avatar">AN</span>':avatar(trainee())}<span>${state.role==='pt'?'PT Anh Nam':e(trainee().name)}<small>${state.role==='pt'?'Huấn luyện viên':'Học viên'}</small></span></div></aside><div class="main-shell">${main}</div><nav class="mobile-nav" aria-label="Điều hướng trên điện thoại">${nav()}</nav>`;
}
function reportHistory(t=trainee()){
  if(!t.report)return [];
  const rows=(t.history||[]).filter(r=>r.date!==t.report.date);
  rows.push({date:t.report.date,...Object.fromEntries(['weight','pbf','smm'].map(k=>[k,Number(t.report.fields[k])]))});
  return rows.sort((a,b)=>a.date.localeCompare(b.date));
}
const progressMetrics={weight:['Cân nặng','kg'],pbf:['Tỷ lệ mỡ','%'],smm:['Cơ xương','kg']};
const numberLabel=value=>new Intl.NumberFormat('vi',{maximumFractionDigits:1,minimumFractionDigits:1}).format(value);
function progressPanel(){
  const rows=reportHistory(),key=state.progressMetric,[label,unit]=progressMetrics[key];
  if(rows.length<2)return `<section class="panel progress-panel"><h2>${state.role==='pt'?'Tiến triển học viên':'Tiến triển của bạn'}</h2><p class="muted">${rows.length?'Đã có một lần đo được xác nhận. Cần thêm lần đo để so sánh theo thời gian.':'Chưa có lần đo được PT xác nhận.'}</p>${rows.length?btn('Xem kết quả lần đo','profile-body','utility-link'):''}</section>`;
  const delta=+(rows.at(-1)[key]-rows[0][key]).toFixed(1);
  return `<section class="panel progress-panel" aria-labelledby="progress-title"><div class="section-line"><h2 id="progress-title">${state.role==='pt'?'Tiến triển học viên':'Tiến triển của bạn'}</h2><small>${rows.length} lần đo đã xác nhận</small></div><div class="progress-controls" role="group" aria-label="Chỉ số trên biểu đồ">${Object.entries(progressMetrics).map(([k,[n]])=>`<button type="button" data-progress="${k}" aria-pressed="${k===key}">${n}</button>`).join('')}</div><div class="trend-summary"><p><strong>${numberLabel(rows.at(-1)[key])}</strong> ${unit}</p><span>${delta>0?'+':delta<0?'−':''}${numberLabel(Math.abs(delta))} ${unit} so với ${dateLabel(rows[0].date).slice(0,5)}</span></div><div class="progress-chart" data-progress-chart="${key}" aria-describedby="progress-context"></div><p class="chart-context" id="progress-context">${label} · ${dateLabel(rows[0].date)} – ${dateLabel(rows.at(-1).date)}. Trục dọc thu gọn; trao đổi với PT để đánh giá theo mục tiêu.</p><details class="measurement-details"><summary>Xem số liệu từng lần đo</summary><table class="simple-table"><caption class="sr-only">${label} theo ngày, đơn vị ${unit}; dữ liệu giả</caption><thead><tr><th scope="col">Ngày đo</th><th scope="col">${label} (${unit})</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${dateLabel(r.date)}</th><td>${numberLabel(r[key])}</td></tr>`).join('')}</tbody></table></details></section>`;
}
function drawProgress(){
  const el=document.querySelector('[data-progress-chart]');if(!el||!window.Charts)return;
  const rows=reportHistory(),key=el.dataset.progressChart,[label,unit]=progressMetrics[key];
  // Local extension to the licensed helper retains actual measurement spacing.
  const labels=rows.map(r=>dateLabel(r.date).slice(0,5)),values=rows.map(r=>r[key]),xPositions=rows.map(r=>Date.parse(r.date+'T00:00:00Z'));
  const nums=rows.map(r=>r[key]),lo=Math.floor(Math.min(...nums))-1,hi=Math.ceil(Math.max(...nums))+1,step=(hi-lo)<=3?0.5:1;
  const ariaLabel=`${label}, ${rows.length} lần đo từ ${dateLabel(rows[0].date)} đến ${dateLabel(rows.at(-1).date)}, mới nhất ${numberLabel(rows.at(-1)[key])} ${unit}. Số liệu đầy đủ ở bảng bên dưới.`;
  Charts.line(el,{labels,series:[{name:label,values}],format:v=>numberLabel(v)+' '+unit,tickFormat:v=>numberLabel(v),height:190,yTicks:Array.from({length:Math.round((hi-lo)/step)+1},(_,i)=>lo+i*step),xPositions,ariaLabel});
}

function heading(title,description='',actions=''){return `<header class="page-heading"><div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</header>`;}
function timeStatus(a){return a.status==='completed'?'<span class="badge good">Đã ghi nhận hoàn thành</span>':a.status==='requested'?'<span class="badge pending">Đề nghị buổi mới</span>':state.request?.appointment===a.id?'<span class="badge pending">Đang có yêu cầu đổi giờ</span>':'<span class="badge">Đã xác nhận</span>';}
function appointmentRow(a){const t=state.trainees.find(t=>t.id===a.trainee);return `<article class="appointment ${a.id==='a2'?'next':''}"><div class="time">${e(a.time)}</div><div><button class="link-button name" type="button" data-action="profile" data-id="${t.id}">${e(t.name)}</button><p>${e(a.type)} · ${a.duration} phút</p>${timeStatus(a)}${a.exercises.length?`<p>${a.exercises.length} bài tập được giao</p>`:''}</div><div class="appointment-action">${btn('Xem buổi hẹn','appointment','small',`data-id="${a.id}"`)}</div></article>`;}
function requestBlock(){if(!state.request)return '';const r=state.request;const a=state.appointments.find(a=>a.id===r.appointment);const t=state.trainees.find(t=>t.id===a.trainee);const canApprove=(state.role==='pt'&&r.by==='trainee')||(state.role==='trainee'&&r.by==='pt');if(state.role==='trainee'&&t.id!==state.selected)return '';return `<article class="attention"><span class="badge pending">Chờ xác nhận</span><h3 style="margin-top:12px">${e(t.name)} · ${r.kind==='new'?'đề nghị buổi mới':'đề nghị đổi giờ'}</h3><p>${r.kind==='new'?'Buổi được đề nghị:':dateLabel(a.date)+' lúc '+a.time+' sang'} <strong>${dateLabel(r.date)} lúc ${r.time}</strong>.</p><p>${r.kind==='new'?'Chưa giữ chỗ cho tới khi PT chấp nhận.':'Buổi cũ vẫn giữ nguyên cho đến khi hai bên chốt.'}</p><div class="button-row">${canApprove?btn(r.kind==='new'?'Chấp nhận buổi hẹn':'Chấp nhận giờ mới','accept-request','primary small')+btn(r.kind==='new'?'Từ chối đề nghị':'Giữ giờ cũ','decline-request','small'):btn('Rút yêu cầu','withdraw-request','small')}</div></article>`;}
function today(){
  const t=trainee();
  if(state.role==='trainee'&&!t.linked)return heading('Hoàn tất kết nối với PT','Hồ sơ đang chờ nhận lời mời.')+`<section class="empty"><h2>Chưa có hồ sơ được chia sẻ</h2><p>Dùng liên kết mời của PT để xác nhận kết nối. Bạn chưa thể xem bản nháp hoặc ghi chú nội bộ.</p></section>`;
  const own=state.appointments.filter(a=>a.date==='2026-10-30'&&(state.role==='pt'||a.trainee===state.selected)).sort((a,b)=>a.time.localeCompare(b.time));
  const complete=own.filter(a=>a.status==='completed').length;
  const head=heading(state.role==='pt'?'Hôm nay của bạn':`Chào ${e(t.name)}`,`Thứ Sáu, 30 tháng 10 · ${state.role==='pt'?'PT Anh Nam':e(goals[t.goal])}`,state.role==='pt'?btn(icon('plus')+'Thêm học viên','intake','')+btn(icon('plus')+'Đặt buổi tập','new-appointment','primary'):btn(icon('chat')+'Nhắn cho PT','chat','primary'));
  return head+`<div class="day-summary"><p><strong>${own.length}</strong> buổi hẹn hôm nay</p><p><strong>${complete}/${own.length}</strong> đã hoàn thành</p><p>${state.role==='pt'?`<strong>${state.trainees.filter(x=>!x.linked).length}</strong> học viên chờ kết nối`:`<strong>${t.remaining}/${t.total}</strong> buổi PT còn lại`}</p></div><div class="split today-layout"><section class="schedule-panel"><div class="section-line"><h2>${state.role==='pt'?'Lịch hôm nay':'Buổi tập của bạn'}</h2>${btn('Xem lịch','calendar','quiet small')}</div><div class="agenda">${own.length?own.map(appointmentRow).join(''):'<div class="empty"><p>Chưa có buổi hẹn hôm nay.</p></div>'}</div>${state.role==='trainee'?`<div class="note self-training"><strong>Hôm nay bạn tự tập?</strong><p>Ghi nhận hoạt động để PT theo dõi. Không trừ buổi PT.</p>${btn(state.selfCheckins.includes(t.id)?icon('check')+'Đã check-in hôm nay':'Check-in tự tập','self-checkin','small',state.selfCheckins.includes(t.id)?'disabled':'')}</div>`:''}</section><aside class="rail" aria-label="Việc cần chú ý">${requestBlock()}${state.role==='pt'?`<article class="attention prep-note"><p class="context-label">Chuẩn bị cho buổi tập</p><h2>Khánh Linh · ${e(state.appointments.find(a=>a.id==='a2')?.time||'sắp tới')}</h2><p>${e(state.trainees.find(x=>x.id==='linh').notes.at(-1)||'Chưa có ghi chú buổi trước.')}</p>${btn('Mở hồ sơ Linh','profile','small','data-id="linh"')}</article><article class="attention"><h3>Hoàng Nam chưa kết nối</h3><p>Nhập hồ sơ và xác nhận báo cáo trước khi gửi lời mời.</p>${btn('Xem hồ sơ Nam','profile','quiet small','data-id="nam"')}</article>`:`<article class="attention"><h2>PT chia sẻ với bạn</h2><p>${e(t.shared||'PT chưa chia sẻ mục tiêu cho bạn.')}</p>${btn('Xem hồ sơ của tôi','profile','small')}</article><article class="attention"><h3>Gói tập của bạn</h3><p>Còn ${t.remaining}/${t.total} buổi cùng PT. Gói đến ${dateLabel(t.end)}.</p>${btn('Xem gói và lịch sử','profile-package','quiet small')}</article>`}</aside></div>${state.role==='trainee'?progressPanel():''}`;
}

function roster(){return heading('Học viên','Mở một hồ sơ để xem lịch, tiến trình và cuộc trao đổi.',btn(icon('plus')+'Thêm học viên','intake','primary'))+`<label class="search">Tìm học viên<input type="search" id="roster-search" placeholder="Nhập tên học viên" autocomplete="off"></label><section id="roster-list" aria-label="Danh sách học viên">${state.trainees.map(t=>`<article class="person-row" data-name="${e(t.name.toLocaleLowerCase('vi'))}">${avatar(t)}<div class="identity"><p><strong>${e(t.name)}</strong></p><small>${e(goals[t.goal])} · Còn ${t.remaining}/${t.total} buổi</small></div><span class="badge ${t.linked?'good':'pending'}">${t.linked?'Đã kết nối':'Chờ kết nối'}</span>${btn('Mở hồ sơ','profile','small',`data-id="${t.id}"`)}</article>`).join('')}</section><p id="search-empty" class="muted" hidden>Không có học viên khớp tên này.</p>`;}
function profile(){const t=trainee();if(state.role==='trainee'&&!t.linked)return today();const back=state.role==='pt'?btn(icon('back')+'Danh sách học viên','roster','back'):'';const tabs=[['overview','Tổng quan'],['body','InBody'],['nutrition','Dinh dưỡng'],['package','Gói tập']];return back+heading(`<span class="profile-heading">${avatar(t)}<span>${e(t.name)}<small class="muted" style="display:block;font-weight:400;font-size:.9375rem;margin-top:6px">${e(goals[t.goal])}</small></span></span>`,'',btn(icon('chat')+(state.role==='pt'?'Trao đổi với học viên':'Nhắn cho PT'),'chat','primary')+(state.role==='pt'&&!t.linked?btn('Mời học viên','invite',''):''))+`<nav class="tabs" aria-label="Thông tin hồ sơ">${tabs.map(([key,label])=>`<button type="button" data-tab="${key}" ${state.tab===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`+({overview:profileOverview,body:profileBody,nutrition:profileNutrition,package:profilePackage}[state.tab]||profileOverview)();}
function profileOverview(){const t=trainee();const a=state.appointments.find(a=>a.trainee===t.id&&a.status!=='completed');return `<div class="split"><section><div class="panel"><h2>Buổi hẹn sắp tới</h2>${a?`<div class="record-summary"><div><strong>${dateLabel(a.date)} · ${a.time}</strong><p>${e(a.type)} · ${a.duration} phút</p></div>${btn('Xem buổi hẹn','appointment','small',`data-id="${a.id}"`)}</div>`:`<p class="muted">Chưa có buổi hẹn.</p>${state.role==='pt'?btn('Đặt buổi tập','new-appointment','small'):btn('Đề nghị một buổi hẹn','propose-new','small')}`}${state.role==='pt'&&t.notes.length?`<p class="muted"><strong>Cần nhớ trước buổi tập:</strong> ${e(t.notes.at(-1))}</p>`:''}<small>Có thể thêm bài tập vào buổi hẹn khi cần.</small></div>${progressPanel()}<div class="panel"><div class="section-line"><h2>Kết quả gần nhất</h2>${t.report?'<span class="badge good">PT đã xác nhận</span>':''}</div>${t.report?`<p class="muted">Lần đo ${dateLabel(t.report.date)} · ${t.report.source==='manual'?'Nhập tay, PT xác nhận':'Nhập từ phiếu, PT đã kiểm tra'}</p><dl class="metric-list">${[['weight','Cân nặng','kg'],['smm','Cơ xương','kg'],['pbf','Tỷ lệ mỡ','%']].map(([key,label,unit])=>`<div><dt>${label}</dt><dd>${e(t.report.fields[key])} <small>${unit}</small></dd></div>`).join('')}</dl>${btn('Xem toàn bộ chỉ số','profile-body','utility-link')}`:`<p class="muted">Chưa có kết quả được PT xác nhận.</p>${state.role==='pt'?btn('Nhập báo cáo InBody','start-report','small'):''}`}</div></section><aside class="rail">${state.role==='pt'?`<div class="section-line"><h2>Ghi chú nội bộ</h2>${icon('lock')}</div><p class="muted">Chỉ PT xem. Không gửi sang học viên.</p>${t.notes.length?t.notes.map(n=>`<article class="private-note"><p>${e(n)}</p><small>PT Anh Nam · ghi chú buổi trước</small></article>`).join(''):'<p class="muted">Chưa có ghi chú nội bộ.</p>'}<form id="private-note-form"><label for="private-note">Thêm ghi chú<textarea id="private-note" name="note" rows="3" maxlength="600" required placeholder="Điều cần nhớ cho buổi tới"></textarea></label><div class="button-row" style="margin-top:12px"><button type="submit">Lưu ghi chú</button></div></form>`:`<h2>PT chia sẻ với bạn</h2><p>${e(t.shared||'Chưa có ghi chú được chia sẻ.')}</p>`}<div class="attention" style="margin-top:24px"><h3>Gói đang sử dụng</h3><p>${dateLabel(t.start)} – ${dateLabel(t.end)}<br>Còn ${t.remaining}/${t.total} buổi PT</p>${btn('Xem gói và lịch sử','profile-package','quiet small')}</div></aside></div>`;}
function profileBody(){const t=trainee();const draftNotice=state.role==='pt'&&state.draft?.trainee===t.id?`<div class="note"><strong>Có bản nháp chưa xác nhận</strong><p>Học viên chưa thấy bản nháp này.</p>${btn('Tiếp tục đối chiếu','resume-report','small')}</div>`:'';return draftNotice+`<div class="section-line"><h2>Kết quả InBody</h2>${state.role==='pt'?btn(icon('plus')+'Nhập lần đo mới','start-report','small'):''}</div>${t.report?`<p class="muted">Ngày đo ${dateLabel(t.report.date)} · Phiếu tổng hợp giả lập · PT đã xác nhận</p><div class="panel"><h3>Chỉ số toàn thân</h3><dl class="metric-list">${metrics.map(([k,label,u])=>`<div><dt>${label}</dt><dd>${e(t.report.fields[k]||'Chưa có')} <small>${u}</small></dd></div>`).join('')}</dl></div><div class="panel"><h3>Phân bố theo vùng</h3><p class="muted">Khối nạc khác khối cơ xương. Số theo vùng không chỉ ra khối lượng từng cơ.</p><div class="table-scroll"><table class="simple-table"><caption class="sr-only">Khối nạc và mỡ theo năm vùng</caption><thead><tr><th scope="col">Vùng</th><th scope="col">Khối nạc (kg)</th><th scope="col">Khối mỡ (kg)</th></tr></thead><tbody>${segmentNames.map(([k,n])=>`<tr><th scope="row">${n}</th><td>${e(t.report.fields[k+'_lean']||'Chưa có')}</td><td>${e(t.report.fields[k+'_fat']||'Chưa có')}</td></tr>`).join('')}</tbody></table></div></div>`:`<div class="empty"><h3>Chưa có bản ghi đã xác nhận</h3><p>${state.role==='pt'?'Bạn có thể nhập và kiểm tra báo cáo ngay, kể cả khi học viên chưa kết nối.':'PT sẽ kiểm tra báo cáo trước khi chia sẻ với bạn.'}</p>${state.role==='pt'?btn('Nhập báo cáo','start-report','primary'):''}</div>`}`;}
function profileNutrition(){const t=trainee();return `<h2>Mục tiêu dinh dưỡng hiện hành</h2>${t.target?`<div class="panel"><p class="muted">PT đã chia sẻ · Bản nháp coaching, có thể điều chỉnh cùng PT</p><dl class="metric-list">${[['kcal','Năng lượng','kcal'],['protein','Protein','g'],['carbs','Carbohydrate','g'],['fat','Chất béo','g']].map(([k,n,u])=>`<div><dt>${n}</dt><dd>${t.target[k]} <small>${u}</small></dd></div>`).join('')}</dl></div>`:'<div class="empty"><p>Chưa có mục tiêu dinh dưỡng được chia sẻ.</p></div>'}<div class="note"><strong>Trao đổi về bữa ăn</strong><p>Ở bản mẫu này, bạn trao đổi bằng tin nhắn. Nhật ký ảnh và AI phân tích món ăn sẽ được quyết định riêng.</p>${btn('Mở cuộc trò chuyện','chat','small')}</div>`;}
function profilePackage(){const t=trainee();return `<div class="split"><section class="panel"><h2>Gói tập hiện tại</h2><p class="large-balance">${t.remaining} <span>/ ${t.total} buổi PT còn lại</span></p><p>Hiệu lực ${dateLabel(t.start)} – ${dateLabel(t.end)}</p><p class="muted">Thời hạn gói và số buổi PT được theo dõi riêng. Check-in tự tập không trừ buổi.</p>${btn('Xem lịch tập','calendar','small')}</section><section class="rail"><h2>Lịch sử sử dụng trong bản mẫu</h2>${t.ledger.length?t.ledger.map(x=>`<article class="private-note"><p><strong>−1 buổi · ${dateLabel(x.date)} ${x.time}</strong></p><small>PT Anh Nam xác nhận hoàn thành</small></article>`).join(''):'<p class="muted">Chưa có thao tác ghi nhận mới trong lần xem này.</p>'}<small>Các buổi đã dùng trước đây là dữ liệu giả có sẵn; bản mẫu chỉ ghi thêm thao tác bạn vừa thử.</small></section></div>`;}
function calendar(){const own=state.appointments.filter(a=>a.date===state.day&&(state.role==='pt'||a.trainee===state.selected));return heading('Lịch tập',state.role==='pt'?'Lịch chung của bạn và học viên.':'Chỉ hiển thị những buổi hẹn của bạn.',state.role==='pt'?btn(icon('plus')+'Đặt buổi tập','new-appointment','primary'):btn('Đề nghị buổi hẹn','propose-new','primary'))+`<div class="week" aria-label="Tuần 26 tháng 10 đến 1 tháng 11">${[['2026-10-26','Thứ 2','26'],['2026-10-27','Thứ 3','27'],['2026-10-28','Thứ 4','28'],['2026-10-29','Thứ 5','29'],['2026-10-30','Thứ 6','30'],['2026-10-31','Thứ 7','31'],['2026-11-01','CN','01']].map(([d,n,x])=>`<button type="button" data-day="${d}" aria-pressed="${d===state.day}"><span>${n}</span><strong>${x}</strong></button>`).join('')}</div><div class="split"><section><h2>Ngày ${dateLabel(state.day)}</h2><div class="agenda">${own.length?own.map(appointmentRow).join(''):`<div class="empty"><h3>Chưa có buổi hẹn</h3><p>${state.role==='pt'?'Chọn thời gian và học viên để tạo lịch. Chưa cần thêm bài tập.':'Bạn có thể gửi đề nghị giờ tập cho PT.'}</p>${btn(state.role==='pt'?'Đặt buổi tập':'Đề nghị buổi hẹn',state.role==='pt'?'new-appointment':'propose-new','small')}</div>`}</div></section><aside class="rail">${requestBlock()||'<h2>Cùng theo dõi một lịch</h2><p class="muted">Buổi hẹn được liên kết trong chat. Yêu cầu đổi giờ chỉ thay lịch sau khi được xác nhận.</p>'}<div class="note">Đặt lịch chưa trừ buổi PT. Buổi đã hoàn thành mới được ghi nhận sử dụng.</div></aside></div>`;}
function eventCard(a){return `<div class="event-message">${icon('calendar')}<div><strong>${e(a.type)}</strong><p>${dateLabel(a.date)} · ${a.time} · ${a.duration} phút</p>${timeStatus(a)}<div style="margin-top:12px">${btn('Xem buổi hẹn','appointment','small',`data-id="${a.id}"`)}</div></div></div>`;}
function chat(){const t=trainee();if(state.role==='pt'&&!t.linked)return heading(`Trao đổi với ${e(t.name)}`)+`<div class="empty"><h2>Học viên chưa kết nối tài khoản</h2><p>Bạn có thể tiếp tục nhập hồ sơ. Gửi lời mời để bắt đầu trao đổi trong ứng dụng.</p>${btn('Mời học viên','invite','primary')}</div>`;if(state.role==='trainee'&&!t.linked)return today();const a=state.appointments.find(a=>a.trainee===t.id);const messages=state.messages.filter(m=>m.trainee===t.id);return heading(state.role==='pt'?`Trao đổi với ${e(t.name)}`:'Trao đổi với PT Anh Nam','Tin nhắn và buổi hẹn được liên kết trong cùng cuộc trò chuyện.',btn('Mở hồ sơ','profile',''))+`${state.role==='pt'?`<label class="select-person">Học viên<select id="chat-person">${state.trainees.filter(t=>t.linked).map(t=>`<option value="${t.id}" ${t.id===state.selected?'selected':''}>${e(t.name)}</option>`).join('')}</select></label>`:''}<div class="chat-layout"><section aria-label="Cuộc trò chuyện"><div class="chat-stream" id="chat-stream">${messages.map(m=>`<article class="message ${m.author===state.role?'mine':''}"><small>${m.author==='pt'?'PT Anh Nam':e(t.name)} · ${e(m.time)}</small><div class="bubble">${e(m.text)}</div></article>`).join('')}${a?`<article class="message system"><small>Buổi hẹn được chia sẻ</small>${eventCard(a)}</article>`:''}${state.request?.appointment===a?.id?`<div class="note"><strong>Đang chờ đổi lịch</strong><p>Giờ hiện tại vẫn giữ nguyên. Mở lịch để xem và xử lý yêu cầu.</p>${btn('Xem yêu cầu','calendar','small')}</div>`:''}${!messages.length&&!a?'<p class="muted">Bắt đầu trao đổi với học viên ở đây.</p>':''}</div><form id="chat-form"><div class="compose"><label for="chat-message">Tin nhắn<textarea id="chat-message" name="message" rows="2" maxlength="1000" placeholder="Viết nội dung trao đổi…" required></textarea></label><button type="submit" class="primary" aria-label="Gửi tin nhắn">${icon('send')}<span>Gửi</span></button></div></form><p class="compose-hint">Nội dung chỉ được mô phỏng trong lần xem này.</p></section><aside class="rail"><h2>${e(t.name)}</h2><p class="muted">${e(goals[t.goal])}</p><p>Còn ${t.remaining}/${t.total} buổi PT</p>${btn('Xem lịch chung','calendar','small')}</aside></div>`;}
function intake(){return btn(icon('back')+'Quay lại học viên','roster','back')+heading('Tiếp nhận học viên','Tạo hồ sơ trước. Kết nối tài khoản có thể hoàn tất sau.')+`<div class="progress-steps" aria-label="Các bước tiếp nhận"><span class="current">1. Hồ sơ</span><span>2. Nhập báo cáo</span><span>3. PT xác nhận</span></div><div class="split"><form id="intake-form"><section class="form-section"><h2>Thông tin ban đầu</h2><div class="form-grid"><label class="full" for="intake-name">Tên học viên<input id="intake-name" name="name" maxlength="80" minlength="2" required placeholder="Ví dụ: Học viên mẫu Mai"></label><label for="intake-goal">Mục tiêu<select id="intake-goal" name="goal">${Object.entries(goals).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label for="intake-phone">Số điện thoại, nếu có<input id="intake-phone" name="phone" type="tel" maxlength="20" placeholder="Dùng số giả trong bản mẫu"></label></div></section><section class="form-section"><h2>Gói đang đăng ký</h2><div class="form-grid"><label for="intake-start">Ngày bắt đầu<input id="intake-start" name="start" type="date" value="2026-10-30" required></label><label for="intake-end">Ngày kết thúc<input id="intake-end" name="end" type="date" value="2026-11-30" required></label><label for="intake-total">Số buổi cùng PT<input id="intake-total" name="total" type="number" min="0" max="500" step="1" value="12" required><span class="hint">Tách riêng thời hạn membership và gói buổi PT.</span></label></div></section><p id="intake-error" class="error" role="alert"></p><div class="form-actions">${btn('Hủy','roster','')}<button type="submit" class="primary">Tạo hồ sơ và nhập báo cáo ${icon('arrow')}</button></div></form><aside class="rail"><h2>Chưa cần email</h2><p class="muted">Bạn có thể nhập và kiểm tra báo cáo ngay khi tiếp nhận. Học viên chỉ xem dữ liệu sau khi xác nhận kết nối với bạn.</p><div class="note"><strong>Chỉ dùng dữ liệu giả</strong><p>Bản mẫu không lưu hồ sơ hoặc tải tài liệu lên máy chủ.</p></div></aside></div>`;}
function reportStart(){const t=trainee();return btn(icon('back')+'Về hồ sơ','profile','back')+heading(`Nhập báo cáo cho ${e(t.name)}`,'Chọn phiếu để tạo bản nháp. Bạn sẽ kiểm tra trước khi xác nhận.')+`<div class="progress-steps"><span>1. Hồ sơ</span><span class="current">2. Nhập báo cáo</span><span>3. PT xác nhận</span></div><div class="split"><section class="panel"><h2>Ảnh hoặc PDF báo cáo</h2><p class="muted">Ở sản phẩm thật, đây là nơi chọn file hoặc chụp phiếu. Trong bản mẫu, chỉ dùng phiếu tổng hợp giả lập.</p><div class="upload-choice">${btn(icon('document')+'Dùng PDF mẫu','sample-pdf','')}${btn(icon('document')+'Dùng ảnh mẫu','sample-image','')}${btn('Nhập chỉ số bằng tay','manual-report','quiet')}</div>${state.busy?'<div class="note" role="status">Đang chuẩn bị bản nháp từ dữ liệu mẫu…</div>':''}</section><aside class="rail"><h2>PT kiểm tra trước khi lưu</h2><p class="muted">Chỉ số toàn thân, phân bố theo vùng và chỉ số mở rộng được đối chiếu với phiếu. Chỗ không có dữ liệu sẽ không bị tự điền.</p><span class="badge ${t.linked?'good':'pending'}">${t.linked?'Đã kết nối học viên':'Có thể nhập trước khi kết nối'}</span></aside></div>`;}
function sourceSheet(){return `<aside class="sample-source" tabindex="0" aria-label="Phiếu tổng hợp giả lập để đối chiếu"><p class="source-label">Phiếu tổng hợp giả lập · Không phải phiếu của hãng</p><h2>${e(trainee().name)}</h2><small>Ngày đo 30/10/2026 · Dữ liệu dựng để duyệt luồng</small><h3 style="margin-top:24px">Toàn thân</h3><dl>${metrics.map(([k,n,u,v])=>`<div><dt>${n}</dt><dd>${v} ${u}</dd></div>`).join('')}</dl><h3>Theo vùng</h3><dl>${segmentNames.map(([k,n],i)=>`<div><dt>${n}<small style="display:block">Khối nạc / mỡ</small></dt><dd>${segmentValues[i][0]} / ${segmentValues[i][1]} kg</dd></div>`).join('')}</dl><small>Reference khối nạc: tay trái 94%, tay phải 96%, thân 101%, chân trái 99%, chân phải 100%.</small><h3 style="margin-top:24px">Mở rộng</h3><dl><div><dt>BMR</dt><dd>1490 kcal/ngày</dd></div><div><dt>Visceral fat level</dt><dd>8</dd></div><div><dt>ECW/TBW</dt><dd>0.378</dd></div><div><dt>Điểm trên phiếu</dt><dd>76</dd></div></dl></aside>`;}
function reviewField(key,name,unit,hint=''){const value=state.draft.fields[key]??'';const attention=value===''||key==='right_arm_lean';return `<div class="review-field ${attention?'attention-field':''}"><label for="metric-${key}">${name}${hint?`<span class="field-hint">${hint}</span>`:''}${key==='right_arm_lean'?'<span class="field-hint">Cần đối chiếu lại với phiếu</span>':''}</label><input id="metric-${key}" name="${key}" data-metric="${key}" type="number" min="0.001" max="${key.endsWith('_ref')?500:10000}" step="any" inputmode="decimal" value="${e(value)}" aria-describedby="unit-${key}" required><span class="muted" id="unit-${key}">${unit}</span></div>`;}
function review(){if(!state.sourceReady||!state.draft)return reportStart();const fields=state.reviewTab==='total'?metrics.map(([k,n,u])=>reviewField(k,n,u)).join(''):state.reviewTab==='segments'?segmentNames.map(([k,n])=>`<section style="margin-bottom:24px"><h3>${n}</h3>${reviewField(k+'_lean','Khối nạc','kg')}${reviewField(k+'_fat','Khối mỡ','kg')}${reviewField(k+'_ref','Khối nạc so tham chiếu','%','Không phải tỷ lệ mỡ cơ thể')}</section>`).join(''):[['bmr','BMR trên phiếu','kcal'],['visceral_level','Mức mỡ nội tạng','level'],['ecw_ratio','ECW/TBW','ratio'],['score','Điểm trên phiếu','điểm']].map(([k,n,u])=>reviewField(k,n,u)).join('');return btn(icon('back')+'Chọn lại nguồn báo cáo','start-report','back')+heading('Đối chiếu trước khi xác nhận',`${e(trainee().name)} · ${state.manual?'Nhập tay':'Bản nháp từ '+state.draft.kind+' mẫu'}`)+`<div class="progress-steps"><span>1. Hồ sơ</span><span>2. Nhập báo cáo</span><span class="current">3. PT xác nhận</span></div><div class="review-layout">${sourceSheet()}<section class="review-editor" aria-label="Chỉ số cần kiểm tra"><span class="badge draft">Bản nháp · Chưa chia sẻ cho học viên</span><div class="note"><p>${state.manual?'Nhập số theo phiếu mẫu bên cạnh. Dữ liệu vẫn cần được đối chiếu trước khi xác nhận.':'Chỉ số được điền từ dữ liệu mẫu, không có OCR thật. Mở cả ba nhóm để kiểm tra; bạn có thể sửa trực tiếp.'}</p></div><nav class="tabs" aria-label="Nhóm chỉ số báo cáo">${[['total','Toàn thân'],['segments','Theo vùng'],['extended','Mở rộng']].map(([k,n])=>`<button type="button" data-review-tab="${k}" ${state.reviewTab===k?'aria-current="page"':''}>${n}</button>`).join('')}</nav><form id="review-form" novalidate>${fields}<div class="review-footer"><p class="muted">Không diễn giải khối nạc thành khối lượng từng nhóm cơ. Nhận xét coaching được ghi riêng.</p><label class="confirm-check"><input type="checkbox" id="report-confirmed" name="confirmed" ${state.draft.confirmed?'checked':''}><span>Tôi đã đối chiếu các nhóm chỉ số với phiếu và xác nhận dữ liệu sẽ chia sẻ.</span></label><p id="review-error" class="error" role="alert"></p><div class="form-actions">${btn('Giữ bản nháp','save-draft','')}<button type="submit" class="primary" id="confirm-report" ${state.draft.confirmed?'':'disabled'}>Xác nhận và lưu bản ghi</button></div></div></form></section></div>`;}
function landing(){
  const t=state.trainees.find(x=>x.id==='linh'),a=state.appointments.find(x=>x.id==='a2');
  const modes=[['profile','Hồ sơ'],['schedule','Lịch hẹn'],['report','Báo cáo']];
  const previews={
    profile:`<div class="proof-person">${avatar(t)}<div><h2>${e(t.name)}</h2><p>${e(goals[t.goal])} · PT Anh Nam</p></div></div><div class="proof-appointment"><small>Buổi tiếp theo</small><p><strong>${a.time}</strong> · ${dateLabel(a.date)}</p><span>${e(a.type)} · ${a.duration} phút</span></div><div class="proof-note"><h3>Trước khi bắt đầu</h3><p>${e(t.notes.at(-1))}</p><small>Ghi chú nội bộ của PT</small></div><dl class="proof-metrics"><div><dt>Cân nặng</dt><dd>${e(t.report?.fields.weight||'—')} <small>kg</small></dd></div><div><dt>Buổi PT còn lại</dt><dd>${t.remaining}<small> / ${t.total}</small></dd></div></dl>`,
    schedule:`<h2>Lịch hẹn đã thống nhất</h2><p>Thứ Sáu, ngày 30 tháng 10</p><div class="proof-appointment"><small>${e(t.name)} · ${e(a.type)}</small><p><strong>${a.time}</strong> · ${a.duration} phút</p><span>${a.status==='completed'?'Đã hoàn thành':'Đã xác nhận'}</span></div><div class="proof-note"><h3>Cần đổi giờ?</h3><p>Học viên gửi đề nghị. Lịch hiện tại giữ nguyên cho đến khi hai bên xác nhận.</p></div><p class="muted">Bài tập đính kèm là tùy chọn. Đặt lịch chưa trừ buổi PT.</p>`,
    report:`<h2>Phiếu đo vào đúng hồ sơ</h2><p>${e(t.name)} · Lần đo ${dateLabel(t.report?.date||'2026-10-23')}</p><dl class="report-preview"><div><dt>Cân nặng</dt><dd>${e(t.report?.fields.weight||'—')} kg</dd></div><div><dt>Khối cơ xương</dt><dd>${e(t.report?.fields.smm||'—')} kg</dd></div><div><dt>Tỷ lệ mỡ</dt><dd>${e(t.report?.fields.pbf||'—')}%</dd></div></dl><div class="proof-note"><h3>PT kiểm tra trước khi chia sẻ</h3><p>Đối chiếu toàn thân, số theo vùng và các chỉ số trên phiếu. Học viên chỉ thấy bản ghi đã xác nhận.</p></div>`
  };
  return `<div class="landing"><header class="landing-nav">${brand()}<div class="landing-nav-actions">${btn('Góc nhìn học viên','landing-trainee','quiet small')}${btn('Mở bản mẫu','landing-pt','primary small')}</div></header><div class="landing-stage"><div class="landing-story"><section class="landing-hero"><h1>Hiểu học viên.<br>Trọn buổi tập.</h1><p>Không gian làm việc của PT: hồ sơ học viên, lịch hẹn và trao đổi trong cùng một nơi.</p>${btn('Khám phá bản mẫu','landing-pt','primary') }<p class="landing-disclosure">Hướng sản phẩm đang được kiểm chứng · Dữ liệu minh họa</p></section><section class="landing-chapter"><h2>Hồ sơ giữ ngữ cảnh</h2><p>Trước buổi tập, mở lại mục tiêu, ghi chú buổi trước và lần đo gần nhất. Cuộc trao đổi đi cùng đúng học viên.</p><p>Đây là công việc bạn từng phải tìm giữa Zalo, Excel và sổ ghi chép.</p>${btn('Mở hồ sơ mẫu','landing-profile','text-action')}</section><section class="landing-chapter"><h2>Hai bên cùng chốt lịch</h2><p>PT sắp buổi hẹn. Học viên theo dõi hoặc đề nghị đổi giờ ngay trong lịch chung. Cuộc hẹn cũng xuất hiện trong chat.</p><p>Thời hạn membership, check-in tự tập và số buổi cùng PT được theo dõi riêng.</p>${btn('Thử luồng đặt lịch','landing-calendar','text-action')}</section><section class="landing-chapter"><h2>Nhập phiếu, giữ quyền duyệt</h2><p>Hướng dự kiến: dùng ảnh hoặc PDF để tạo bản nháp báo cáo cơ thể. PT đối chiếu, sửa và xác nhận trước khi học viên xem.</p><p>Ở bản mẫu, dữ liệu được dựng sẵn để thử bước kiểm duyệt. OCR thật chưa hoạt động.</p>${btn('Thử bước đối chiếu','landing-report','text-action')}</section></div><aside class="landing-product"><div class="product-stage"><div class="preview-selector" role="group" aria-label="Nội dung sản phẩm minh họa">${modes.map(([key,n])=>`<button type="button" data-landing-mode="${key}" aria-pressed="${state.landingMode===key}">${n}</button>`).join('')}</div><div class="live-proof" data-ui>${previews[state.landingMode]}</div><p class="proof-caption">Màn hình minh họa từ bản mẫu tương tác</p></div></aside></div><section class="landing-close"><div><h2>PT quản lý. Học viên theo sát.</h2><p>Web dành cho cả hai vai trò. Trải nghiệm ứng dụng đang định hướng Android trước; chưa có bản cài để tải.</p></div><div><h3>Thử một buổi làm việc</h3><p>Mở lịch, xem hồ sơ và gửi một tin nhắn trong bản mẫu.</p>${btn('Khám phá bản mẫu','landing-pt','primary')}</div></section><footer class="landing-footer"><p>FitSync · Không gian làm việc của PT</p><p>Bản mẫu thiết kế · Không đăng ký, không thanh toán</p></footer></div>`;
}

function render(){document.getElementById('review-role').value=state.role;document.getElementById('review-scenario').value=state.scenario;const views={today,roster,profile,calendar,chat,intake,review,landing,reportStart};const page=(views[state.page]||today)();$('#app').innerHTML=shell(page);drawProgress();}
function showDialog(title,content){const d=$('#app-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn(icon('close'),'close-dialog','icon-button','aria-label="Đóng hộp thoại"')}</div>${content}`;d.showModal();const first=d.querySelector('input:not([type=hidden]),select,textarea');if(first)first.focus();}
function closeDialog(){const d=$('#app-dialog');if(d.open)d.close();}
function appointmentDialog(id){const a=state.appointments.find(a=>a.id===id);if(!a)return;state.selected=a.trainee;const t=trainee();showDialog(e(t.name),`<p><strong>${dateLabel(a.date)} · ${a.time}</strong><br>${e(a.type)} · ${a.duration} phút</p>${timeStatus(a)}<div class="note"><strong>Bài tập trong buổi</strong>${a.exercises.length?`<p>${a.exercises.map(x=>e(x)).join('<br>')}</p>`:'<p>Chưa gắn bài tập. Buổi hẹn vẫn dùng bình thường.</p>'}${state.role==='pt'&&a.status!=='completed'?btn('Thêm bài tùy chọn','add-exercise','small',`data-id="${a.id}"`):''}</div><div class="button-row">${btn('Mở hồ sơ','dialog-profile','small')}${btn('Trao đổi về buổi này','dialog-chat','small')}${a.status!=='completed'?btn(state.role==='pt'?'Đề xuất đổi giờ':'Đề nghị đổi giờ','reschedule','small',`data-id="${a.id}"`):''}</div>${state.role==='pt'?`<div class="dialog-actions">${btn(a.status==='completed'?icon('check')+'Đã ghi nhận buổi này':'Ghi nhận hoàn thành','complete-appointment','primary',`data-id="${a.id}" ${a.status!=='confirmed'?'disabled':''}`)}</div>`:''}`);}
function scheduleForm(id=null){const a=state.appointments.find(a=>a.id===id);closeDialog();showDialog(a?'Đề xuất giờ mới':state.role==='pt'?'Đặt buổi tập':'Đề nghị buổi hẹn',`<form id="schedule-form" data-id="${a?.id||''}" class="dialog-grid">${!a&&state.role==='pt'?`<label for="schedule-trainee">Học viên<select id="schedule-trainee" name="trainee">${state.trainees.map(t=>`<option value="${t.id}" ${t.id===state.selected?'selected':''}>${e(t.name)}</option>`).join('')}</select></label>`:''}<div class="form-grid"><label for="schedule-date">Ngày<input id="schedule-date" type="date" name="date" value="${a?.date||state.day}" required></label><label for="schedule-time">Giờ bắt đầu<input id="schedule-time" type="time" name="time" value="${a?.time||'18:00'}" required></label></div><label for="schedule-duration">Thời lượng<select id="schedule-duration" name="duration"><option value="60">60 phút</option><option value="45">45 phút</option><option value="30">30 phút</option></select></label><p class="muted">${a?'Buổi hiện tại giữ nguyên cho đến khi bên còn lại xác nhận.':'Không cần thêm bài tập để tạo buổi hẹn.'}</p><p class="error" id="schedule-error" role="alert"></p><div class="dialog-actions">${btn('Quay lại','close-dialog','')}<button class="primary" type="submit">${a||state.role==='trainee'?'Gửi đề nghị':'Lưu buổi hẹn'}</button></div></form>`);}
function acceptRequest(){const r=state.request;if(!r)return;const a=state.appointments.find(a=>a.id===r.appointment);const authorized=(state.role==='pt'&&r.by==='trainee')||(state.role==='trainee'&&r.by==='pt');if(!authorized){toast('Yêu cầu đang chờ bên còn lại xác nhận.');return;}if(isConflict(a.trainee,r.date,r.time,r.duration,a.id)){toast('Giờ đề nghị trùng buổi đã xác nhận. Giờ cũ vẫn giữ nguyên.');return;}a.date=r.date;a.time=r.time;a.duration=r.duration;a.status='confirmed';state.day=r.date;state.request=null;render();toast(r.kind==='new'?'Đã xác nhận buổi hẹn mới.':'Đã chốt giờ mới. Lịch và thẻ trong chat cùng được cập nhật.');}
function isConflict(traineeId,date,time,duration,exclude){const [h,m]=time.split(':').map(Number);const start=h*60+m;return state.appointments.some(a=>{if(a.id===exclude||['completed','requested'].includes(a.status)||a.date!==date)return false;const [ah,am]=a.time.split(':').map(Number);const as=ah*60+am;return start<as+a.duration&&start+duration>as;});}
function prepareReport(manual=false,kind='PDF'){const job=++sourceJob;state.manual=manual;state.reviewTab='total';state.sourceReady=false;state.busy=!manual;state.draft=null;state.page='reportStart';render();if(state.scenario==='unavailable'&&!manual){state.busy=false;showDialog('Chưa có bản nháp OCR',`<p>Không thể đọc phiếu lúc này. Bạn vẫn có thể tiếp tục nhập và đối chiếu bằng tay.</p><p class="muted">Đây là tình huống lỗi giả lập, không gọi nhà cung cấp thật.</p><div class="dialog-actions">${btn('Quay lại hồ sơ','dialog-profile','')}${btn('Tiếp tục nhập tay','manual-report','primary')}</div>`);return;}const finish=()=>{if(job!==sourceJob)return;const fields=manual?Object.fromEntries(Object.keys(sampleFields()).map(k=>[k,''])):sampleFields();if(state.scenario==='missing'&&!manual)fields.left_arm_lean='';state.draft={fields,confirmed:false,kind,trainee:state.selected};state.sourceReady=true;state.busy=false;if(state.page==='reportStart')go('review');else{render();toast('Bản nháp đã sẵn sàng. Bạn có thể tiếp tục từ hồ sơ.');}};if(manual)finish();else setTimeout(finish,420);}
function invite(){showDialog('Kết nối với học viên',`<p>${e(trainee().name)} sẽ xác nhận PT trước khi xem dữ liệu được chia sẻ.</p><div class="note"><strong>Liên kết mời giả lập</strong><p>fitsync.example/invite/demo-b1a</p><small>Không phải link hoặc mã QR có quyền truy cập thật.</small></div><div class="dialog-actions">${btn('Để sau','close-dialog','')}${btn('Mô phỏng học viên nhận lời mời','accept-invite','primary')}</div>`);}
const actions={
  today:()=>go('today'),roster:()=>go('roster'),calendar:()=>go('calendar'),chat:()=>go('chat'),intake:()=>go('intake'),profile:n=>{if(n.dataset.id)state.selected=n.dataset.id;go('profile');},'profile-body':()=>go('profile','body'),'profile-package':()=>go('profile','package'),
  'start-report':()=>{state.sourceReady=false;go('reportStart');},'sample-pdf':()=>prepareReport(false,'PDF'),'sample-image':()=>prepareReport(false,'ảnh'),'manual-report':()=>{closeDialog();prepareReport(true,'nhập tay');},
  'resume-report':()=>go('review'),'save-draft':()=>{go('profile','body');toast('Đã giữ bản nháp trong lần xem này. Học viên chưa thấy dữ liệu.');},
  appointment:n=>appointmentDialog(n.dataset.id),'close-dialog':closeDialog,'dialog-profile':()=>{closeDialog();go('profile');},'dialog-chat':()=>{closeDialog();go('chat');},
  'new-appointment':()=>scheduleForm(),'propose-new':()=>scheduleForm(),reschedule:n=>scheduleForm(n.dataset.id),
  'accept-request':acceptRequest,'decline-request':()=>{if(state.request?.kind==='new')state.appointments=state.appointments.filter(a=>a.id!==state.request.appointment);state.request=null;render();toast('Giữ nguyên giờ cũ. Yêu cầu đã được xử lý.');},'withdraw-request':()=>{if(state.request?.kind==='new')state.appointments=state.appointments.filter(a=>a.id!==state.request.appointment);state.request=null;render();toast('Đã rút yêu cầu, giờ cũ giữ nguyên.');},
  'complete-appointment':n=>{const a=state.appointments.find(a=>a.id===n.dataset.id);if(state.role!=='pt'||!a||a.status!=='confirmed')return;if(state.request?.appointment===a.id){toast('Xử lý yêu cầu đổi giờ trước khi ghi nhận hoàn thành.');return;}const t=state.trainees.find(t=>t.id===a.trainee);if(a.type==='Buổi cùng PT'&&t.remaining<1){toast('Gói không còn buổi PT. Cần xử lý gói trước khi ghi nhận.');return;}a.status='completed';if(a.type==='Buổi cùng PT'){t.remaining--;t.ledger.push({appointment:a.id,date:a.date,time:a.time});}closeDialog();render();toast(a.type==='Buổi cùng PT'?'Đã ghi nhận hoàn thành và sử dụng 1 buổi PT.':'Đã ghi nhận buổi tư vấn, không trừ gói PT.');},
  'self-checkin':()=>{if(!state.selfCheckins.includes(state.selected))state.selfCheckins.push(state.selected);render();toast('Đã check-in tự tập. Số buổi PT không thay đổi.');},
  invite,'accept-invite':()=>{trainee().linked=true;closeDialog();state.role='trainee';go('today');toast('Đã mô phỏng kết nối với PT. Bạn đang xem góc nhìn học viên.');},
  'add-exercise':n=>{const id=n.dataset.id;closeDialog();showDialog('Thêm bài tập tùy chọn',`<form id="exercise-form" data-id="${id}" class="dialog-grid"><label for="exercise-name">Tên bài<input id="exercise-name" name="name" value="Goblet squat" maxlength="100" required></label><div class="form-grid"><label for="exercise-sets">Số hiệp<input id="exercise-sets" name="sets" type="number" min="1" max="20" value="3" required></label><label for="exercise-reps">Số lần mỗi hiệp<input id="exercise-reps" name="reps" type="number" min="1" max="100" value="10" required></label></div><label for="exercise-note">Hướng dẫn thêm<textarea id="exercise-note" name="note" rows="2" maxlength="300" placeholder="Có thể để trống"></textarea></label><p class="muted">Bản mẫu chưa tích hợp thư viện OpenGym. Chi tiết tạ, nghỉ, bài theo thời gian sẽ chốt sau.</p><div class="dialog-actions">${btn('Hủy','close-dialog','')}<button class="primary" type="submit">Gắn vào buổi hẹn</button></div></form>`);},
  'landing-profile':()=>{state.role='pt';state.selected='linh';go('profile');},'landing-calendar':()=>{state.role='pt';go('calendar');},'landing-report':()=>{state.role='pt';state.selected='linh';go('reportStart');},
  'landing-pt':()=>{state.selected='linh';state.role='pt';go('today');},'landing-trainee':()=>{state.selected='linh';state.role='trainee';go('today');},
};
document.addEventListener('click',event=>{const n=event.target.closest('[data-action],[data-nav],[data-tab],[data-day],[data-review-tab],[data-progress],[data-landing-mode]');if(!n||n.disabled)return;if(n.dataset.progress){state.progressMetric=n.dataset.progress;render();document.querySelector('[data-progress="'+state.progressMetric+'"]')?.focus({preventScroll:true});return;}if(n.dataset.landingMode){const y=scrollY;state.landingMode=n.dataset.landingMode;render();window.scrollTo(0,y);document.querySelector('[data-landing-mode="'+state.landingMode+'"]')?.focus({preventScroll:true});return;}if(n.dataset.nav){go(n.dataset.nav);return;}if(n.dataset.tab){state.tab=n.dataset.tab;render();return;}if(n.dataset.day){state.day=n.dataset.day;render();return;}if(n.dataset.reviewTab){state.reviewTab=n.dataset.reviewTab;render();return;}actions[n.dataset.action]?.(n);});
document.addEventListener('input',event=>{const n=event.target;if(n.matches('[data-metric]')&&state.draft)state.draft.fields[n.dataset.metric]=n.value;if(n.id==='roster-search'){const query=n.value.trim().toLocaleLowerCase('vi');let found=0;document.querySelectorAll('#roster-list .person-row').forEach(row=>{row.hidden=!row.dataset.name.includes(query);if(!row.hidden)found++;});$('#search-empty').hidden=found>0;}});
document.addEventListener('change',event=>{const n=event.target;if(n.id==='report-confirmed'&&state.draft){state.draft.confirmed=n.checked;$('#confirm-report').disabled=!n.checked;}if(n.id==='review-role'){sourceJob++;state.role=n.value;go('today');}if(n.id==='review-scenario'){sourceJob++;state.scenario=n.value;state.sourceReady=false;state.draft=null;go(state.role==='pt'?'reportStart':'today');}if(n.id==='chat-person'){state.selected=n.value;render();}});
document.addEventListener('submit',event=>{
  const form=event.target;if(!['intake-form','private-note-form','chat-form','schedule-form','review-form','exercise-form'].includes(form.id))return;event.preventDefault();const f=new FormData(form);
  if(form.id==='intake-form'){const name=String(f.get('name')).trim(),start=String(f.get('start')),end=String(f.get('end')),total=Number(f.get('total'));if(name.length<2||end<start||!Number.isInteger(total)||total<0||total>500){$('#intake-error').textContent=end<start?'Ngày kết thúc cần từ ngày bắt đầu trở đi.':'Kiểm tra tên và số buổi PT.';return;}const id='new-'+Date.now();state.trainees.push({id,name,goal:String(f.get('goal')),linked:false,start,end,total,remaining:total,report:null,notes:[],shared:'',ledger:[],target:null});state.selected=id;go('reportStart');toast('Đã tạo hồ sơ giả lập. Bạn có thể nhập báo cáo trước khi kết nối.');}
  if(form.id==='private-note-form'){const value=String(f.get('note')).trim();if(!value)return;trainee().notes.push(value);render();toast('Đã lưu ghi chú nội bộ. Học viên không thấy ghi chú này.');}
  if(form.id==='chat-form'){const value=String(f.get('message')).trim();if(!value)return;state.messages.push({trainee:state.selected,author:state.role,text:value,time:'Vừa xong'});render();$('#chat-message').focus();$('#chat-stream').scrollTop=$('#chat-stream').scrollHeight;toast('Đã gửi tin nhắn trong bản mẫu.');}
  if(form.id==='schedule-form'){const id=form.dataset.id,date=String(f.get('date')),time=String(f.get('time')),duration=Number(f.get('duration')),tId=String(f.get('trainee')||state.selected);const existing=state.appointments.find(a=>a.id===id);if(isConflict(tId,date,time,duration,id)){$('#schedule-error').textContent='Giờ này trùng một buổi đã xác nhận. Chọn giờ khác.';return;}if(existing){if(state.request){$('#schedule-error').textContent='Đang có yêu cầu đổi giờ. Xử lý yêu cầu hiện tại trước.';return;}state.request={appointment:id,date,time,duration,by:state.role};}else if(state.role==='trainee'){if(state.request){$('#schedule-error').textContent='Bạn đang có một yêu cầu chờ xử lý.';return;}const aid='a-'+Date.now();state.appointments.push({id:aid,trainee:tId,date,time,duration,type:'Buổi cùng PT',status:'requested',exercises:[]});state.request={appointment:aid,date,time,duration,by:'trainee',kind:'new'};}else{state.appointments.push({id:'a-'+Date.now(),trainee:tId,date,time,duration,type:'Buổi cùng PT',status:'confirmed',exercises:[]});}state.day=existing?existing.date:date;closeDialog();go('calendar');toast(existing?'Đã gửi đề nghị. Giờ cũ vẫn giữ nguyên.':state.role==='trainee'?'Đã gửi đề nghị buổi mới, đang chờ PT xác nhận.':'Đã lưu buổi hẹn, chưa trừ số buổi PT.');}
  if(form.id==='review-form'){if(!state.draft?.confirmed)return;const invalid=Object.keys(sampleFields()).filter(k=>{const v=Number(state.draft.fields[k]);return state.draft.fields[k]===''||!Number.isFinite(v)||v<=0;});if(invalid.length){const k=invalid[0];state.reviewTab=segmentNames.some(([s])=>k.startsWith(s))?'segments':metrics.some(m=>m[0]===k)?'total':'extended';render();$('#review-error').textContent='Còn chỉ số chưa có hoặc không hợp lệ. Đối chiếu với phiếu mẫu và nhập trước khi xác nhận.';$('#metric-'+k)?.focus();return;}const v=Object.fromEntries(Object.entries(state.draft.fields).map(([k,v])=>[k,Number(v)]));if(Math.abs(v.fat/v.weight*100-v.pbf)>2||v.smm+v.fat>v.weight){state.reviewTab='total';render();$('#review-error').textContent='Khối mỡ, tỷ lệ mỡ hoặc tổng cơ và mỡ chưa nhất quán với cân nặng. Kiểm tra lại phiếu.';return;}if(trainee().report){const previous=trainee().report;trainee().history=(trainee().history||[]).filter(r=>r.date!==previous.date);trainee().history.push({date:previous.date,...Object.fromEntries(['weight','pbf','smm'].map(k=>[k,Number(previous.fields[k])]))});}trainee().report={fields:{...state.draft.fields},date:'2026-10-30',source:state.manual?'manual':'ocr_reviewed'};state.draft=null;state.sourceReady=false;go('profile','body');toast('PT đã xác nhận bản ghi. Học viên được xem sau khi kết nối.');}
  if(form.id==='exercise-form'){const a=state.appointments.find(a=>a.id===form.dataset.id);if(!a||state.role!=='pt')return;const name=String(f.get('name')).trim();a.exercises.push(`${name} · ${f.get('sets')} hiệp × ${f.get('reps')} lần${f.get('note')?' · '+String(f.get('note')).trim():''}`);closeDialog();appointmentDialog(a.id);toast('Đã gắn bài tập vào cùng buổi hẹn.');}
});
$('#reset-prototype').addEventListener('click',()=>{sourceJob++;closeDialog();state=initialState();setHash();render();toast('Đã đặt lại toàn bộ dữ liệu mẫu.');});
$('#landing-preview').addEventListener('click',()=>go('landing'));
$('#app-dialog').addEventListener('click',event=>{if(event.target===$('#app-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
const initialHash=location.hash.slice(1).split('/');if(['pt','trainee'].includes(initialHash[0]))state.role=initialHash[0];if(['today','roster','profile','calendar','chat','intake','reportStart','review','landing'].includes(initialHash[1]))state.page=initialHash[1];if(state.role==='trainee'&&['intake','review','reportStart','roster'].includes(state.page))state.page='today';setHash();render();
new ResizeObserver(()=>document.documentElement.style.setProperty('--review-height',document.querySelector('.reviewbar').getBoundingClientRect().height+'px')).observe(document.querySelector('.reviewbar'));
